records.command:
$env:PATH = 'C:/Users/offic/.cache/codex-runtimes/codex-primary-runtime/dependencies/native/git/cmd;' + $env:PATH
$releaseRoot039 = Join-Path (Get-Location) ('.dip-local/release-0.3.9-source-' + [guid]::NewGuid().ToString('N').Substring(0,8))
New-Item -ItemType Directory -Path $releaseRoot039 | Out-Null
$archive039 = $releaseRoot039 + '.tar'
git archive --format=tar --output=$archive039 78f4f8eb543bbe447c1577fbdedb116c3739b699
if ($LASTEXITCODE -ne 0) { throw 'Git archive failed' }
tar -xf $archive039 -C $releaseRoot039
if ($LASTEXITCODE -ne 0) { throw 'Extraction failed' }
Set-Content -LiteralPath '.dip-local/release-0.3.9-source-path.txt' -Value $releaseRoot039
Push-Location -LiteralPath $releaseRoot039
try {
  npm pack --json
  if ($LASTEXITCODE -ne 0) { throw 'Package build failed' }
  node scripts/package-smoke.mjs
  if ($LASTEXITCODE -ne 0) { throw 'Package smoke failed' }
} finally { Pop-Location }
Copy-Item -LiteralPath (Join-Path $releaseRoot039 'vxu-labs-dip-0.3.9.tgz') -Destination '.dip-local/vxu-labs-dip-0.3.9.tgz'
Write-Output 'Clean committed package built and smoke-tested.'
